/** Actual AssemblyScript command plus caller-driven reactor exports.
 * Stage selected binding/mode sources without editing generated bytes. Exactly
 * one actual backend and complete generated Codec are selected by that graph.
 */
import {Session,Capability,NativeApi,RobotMsg,RobotCodec} from './binding';
import {MODE} from './mode';
import {credit,marker,proc_exit} from './wasi_stdio';
import {headerMatches} from './header';
let session:Session|null=null,cap:Capability|null=null;
let started:bool=false,closed:bool=false,denied:bool=false;
let received:u32=0,polls:u32=0,first:u32=0,cleanup:u32=0;
const codec=new RobotCodec();
function full(v:RobotMsg):bool {
  if(!headerMatches(v)||v.header.frame_id!='xarm-base'||v.state!=4||v.mode!=0||v.cmdnum!=3||v.mt_brake!=85||v.mt_able!=42||v.err!=7||v.warn!=9||v.angle.length!=7||v.pose.length!=6||v.offset.length!=6)return false;
  return v.angle[0]==0.0&&v.angle[1]==0.25&&v.angle[2]==-0.5&&v.angle[3]==1.0&&v.angle[4]==-1.25&&v.angle[5]==1.5&&v.angle[6]==-1.75&&
    v.pose[0]==125.5&&v.pose[1]==-250.25&&v.pose[2]==375.0&&v.pose[3]==0.25&&v.pose[4]==-0.5&&v.pose[5]==0.75&&
    v.offset[0]==1.0&&v.offset[1]==2.0&&v.offset[2]==3.0&&v.offset[3]==-0.125&&v.offset[4]==0.25&&v.offset[5]==-0.5;
}
function finish(error:u32):u32 {
  if(closed)return first?first:9;closed=true;first=error;
  const owner=session;if(owner!==null){const codes=owner.close();for(let i=0;i<codes.length;++i)if(!cleanup&&codes[i])cleanup=codes[i];}
  if(!first)first=cleanup;return first;
}
export function xarm_robot_msg_initialize(mode:u32):u32 {
  if(started||closed)return 9;if(mode>1)return 22;started=true;
  session=new Session(new NativeApi(),1);const owner=session!;
  if(owner.status)return finish(owner.status);
  if(RobotCodec.maxWireBytes<1||RobotCodec.maxWireBytes>32768)return finish(90);
  cap=owner.open('xarm-robot-msg');const selected=cap!;
  if(mode==0){denied=selected.openStatus==13&&!selected.isOpen();return finish(denied?0:selected.openStatus?selected.openStatus:22);}
  if(selected.openStatus)return finish(selected.openStatus);
  const error=selected.subscribe();return error?finish(error):0;
}
/** A single caller credit permits only one native poll and one full decode. */
export function xarm_robot_msg_poll_once():u32 {
  if(!started||closed)return 9;if(polls++>=64)return finish(110);
  const selected=cap;if(selected===null)return finish(9);
  const reply=selected.poll(RobotCodec.maxWireBytes);
  if(reply.status==11)return 11;if(reply.status)return finish(reply.status);
  if(!codec.valid(reply.bytes))return finish(22);
  const value=codec.decode(reply.bytes);if(!full(value))return finish(22);received++;return 0;
}
export function xarm_robot_msg_close():u32{return finish(first);}
export function received_count():u32{return received;}
export function denied_verified():bool{return denied;}
export function cleanup_error():u32{return cleanup;}
export function _start():void {
  let error=xarm_robot_msg_initialize(MODE);
  if(MODE==0){if(!error&&(!denied||received!=0))error=22;}
  else if(!error){
    for(let i=0;i<64&&received==0;++i){error=credit();if(error)break;error=xarm_robot_msg_poll_once();if(error==11){error=0;continue;}if(error)break;}
    if(!error&&received!=1)error=110;const retired=xarm_robot_msg_close();if(!error)error=retired;
  }
  if(!error)error=cleanup;if(!error)error=marker(MODE?'PASS_XARM_ROBOT_MSG_FULL_VALUE\n':'PASS_XARM_ROBOT_MSG_DEFAULT_DENIED\n');
  if(error)proc_exit(error);
}
